#!/usr/bin/env python3
from __future__ import annotations
from datetime import datetime
from pathlib import Path
import base64, hashlib, json, subprocess, tempfile, zipfile

ROOT=Path.cwd()
FILES=json.loads('[{"path": "app/AppProviders.tsx", "expected_sha256": "15996972f040aecaa1280f4d4948b5e760cd05e170de6fb2972749d640247c8c", "content_b64": ""}, {"path": "app/context/CoinsContext.tsx", "expected_sha256": "42e1f4d19c543e1a7b916e39fe4c0987cd3eee8710a82d139dfbf2043bdb5811", "content_b64": ""}, {"path": "app/context/PurchasesContext.tsx", "expected_sha256": "385967eb20e7b47e244ed9c723dbe6199df9a23bb7aff2a57bf372a27206ecbc", "content_b64": ""}, {"path": "app/context/UserContext.tsx", "expected_sha256": "a11f7e7d8d24cff1b3dcb9b7d57e47b161328ff410d27580920c4a586df4269d", "content_b64": ""}, {"path": "app/(tabs)/shop.tsx", "expected_sha256": "8e2644a751bea689777a4e7a837fc32175b70ae4d8009a382c7b48236514121d", "content_b64": ""}]')

class InstallError(RuntimeError):
    pass

def sha256(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()

def syntax_check(staged: list[Path]) -> None:
    node_script = r"""
const fs = require('fs');
const ts = require('typescript');
let failed = false;
for (const file of process.argv.slice(1)) {
  const source = fs.readFileSync(file, 'utf8');
  const result = ts.transpileModule(source, {
    fileName: file,
    reportDiagnostics: true,
    compilerOptions: {
      jsx: ts.JsxEmit.ReactJSX,
      target: ts.ScriptTarget.ES2020,
      module: ts.ModuleKind.ESNext,
    },
  });
  const errors = (result.diagnostics || []).filter(
    d => d.category === ts.DiagnosticCategory.Error
  );
  if (errors.length) {
    failed = true;
    console.error(`Syntax errors in ${file}:`);
    for (const error of errors) {
      console.error(ts.flattenDiagnosticMessageText(error.messageText, '\n'));
    }
  }
}
process.exit(failed ? 1 : 0);
"""
    result=subprocess.run(['node','-e',node_script,*[str(p) for p in staged]],cwd=ROOT,text=True,capture_output=True)
    if result.returncode != 0:
        raise InstallError(result.stderr.strip() or result.stdout.strip())

def main() -> int:
    try:
        missing=[]
        mismatched=[]
        for item in FILES:
            path=ROOT/item['path']
            if not path.is_file():
                missing.append(item['path'])
            elif sha256(path) != item['expected_sha256']:
                mismatched.append(item['path'])
        if missing:
            raise InstallError('Missing required files: ' + ', '.join(missing))
        if mismatched:
            raise InstallError('These files changed after the debug ZIP was created, so nothing was written: ' + ', '.join(mismatched) + '. Create a fresh account-isolation ZIP before retrying.')

        stamp=datetime.now().strftime('%Y%m%d-%H%M%S')
        backup=ROOT/'backups'/f'before_account_isolation_fix_{stamp}.zip'
        backup.parent.mkdir(parents=True,exist_ok=True)
        with zipfile.ZipFile(backup,'w',zipfile.ZIP_DEFLATED) as z:
            for item in FILES:
                path=ROOT/item['path']
                z.write(path,path.relative_to(ROOT))

        with tempfile.TemporaryDirectory(prefix='nova-account-isolation-') as tmp:
            tmp_root=Path(tmp)
            staged=[]
            for item in FILES:
                target=tmp_root/item['path']
                target.parent.mkdir(parents=True,exist_ok=True)
                target.write_bytes(base64.b64decode(item['content_b64']))
                staged.append(target)
            syntax_check(staged)
            for item in FILES:
                source=tmp_root/item['path']
                target=ROOT/item['path']
                target.write_bytes(source.read_bytes())

        print('✅ Account and guest data isolation installed.')
        print('✅ Guest purchases no longer merge legacy/global ownership.')
        print('✅ Apple purchases and restores now require a signed-in account.')
        print('✅ Pending IAPs cannot grant into a different account or guest.')
        print('✅ Previous-account coins clear before guest hydration renders.')
        print('✅ Sign-out clears stale guest coin/purchase/customization caches.')
        print('✅ Removed dev coin, theme, and purchase grant deep-link listeners.')
        print('✅ Syntax check passed for every changed file.')
        print(f'✅ Backup: {backup.relative_to(ROOT)}')
        print()
        print('Next: sign in once, sign out once, then tap Continue as Guest.')
        print('Then restart Metro with: npx expo start --dev-client --clear')
        return 0
    except InstallError as error:
        print('❌ Nothing was written.')
        print('Reason:', error)
        return 1
    except Exception as error:
        print('❌ Nothing was written.')
        print(f'Unexpected error: {type(error).__name__}: {error}')
        return 1

if __name__ == '__main__':
    raise SystemExit(main())
